referenceSolutions.javascript:
export function solve(values, predicate) {
  const p = (x) =>
    predicate.kind === "gt"
      ? x > predicate.value
      : predicate.kind === "even"
        ? typeof x === "number" && x % 2 === 0
        : x === predicate.value;
  let start = 0;
  while (start < values.length && p(values[start])) start++;
  return values.slice(start);
}

referenceSolutions.typescript:
export function solve(values: any[], predicate: { kind: string; value?: any }): any {
  const p = (x: any): boolean =>
    predicate.kind === "gt"
      ? x > predicate.value
      : predicate.kind === "even"
        ? typeof x === "number" && x % 2 === 0
        : x === predicate.value;
  let start = 0;
  while (start < values.length && p(values[start])) start++;
  return values.slice(start);
}
